"use client"

import { zodResolver } from "@hookform/resolvers/zod"
import { Loader2 } from "lucide-react"
import * as z from "zod"

import * as React from "react"
import { useForm } from "react-hook-form"

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Form } from "@/components/ui/form"

import { TsFormLayout } from "./ts-form-layout"
import { generateZodSchema } from "./ts-form-schema"
import { TsFormLayout as LayoutType, TsFieldDef, TsFormButton, TsFormConfirmation } from "./types"

export interface TsFormProps {
  layout: LayoutType
  fields: Record<string, TsFieldDef>
  values?: Record<string, unknown>
  buttons?: TsFormButton[]
  errors?: Record<string, string>
  onSubmit?: (data: Record<string, unknown>, action: string) => void
  readOnly?: boolean
  className?: string
}

export function TsForm({
  layout,
  fields,
  values,
  buttons = [],
  errors,
  onSubmit,
  className,
}: Omit<TsFormProps, "readOnly">) {
  // 1. Generate Schema based on fields
  const formSchema = React.useMemo(() => generateZodSchema(fields), [fields])
  type FormValues = z.infer<typeof formSchema>

  // 2. Initialize Form
  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: (values as FormValues) || {},
    mode: "onChange",
  })

  // Update form values when props change
  React.useEffect(() => {
    if (values) {
      form.reset(values as FormValues)
    }
  }, [values, form])

  // Handle external errors
  React.useEffect(() => {
    if (errors) {
      Object.entries(errors).forEach(([key, message]) => {
        form.setError(key as keyof FormValues, { type: "manual", message })
      })
    }
  }, [errors, form])

  const [submittingAction, setSubmittingAction] = React.useState<string | null>(null)

  // Confirmation State
  const [confirmation, setConfirmation] = React.useState<{
    isOpen: boolean
    config: TsFormConfirmation | null
    pendingAction: string | null
    pendingData: FormValues | null
  }>({ isOpen: false, config: null, pendingAction: null, pendingData: null })

  // 3. Handle Submit (called by form onSubmit)
  const onFormSubmit = (data: FormValues) => {
    // This logic handles implicit submission via Enter key or direct button click

    if (submittingAction) {
      onSubmit?.(data as Record<string, unknown>, submittingAction)
      setSubmittingAction(null)
    } else {
      // Default submit (e.g. Enter key) - find primary submit button
      const submitBtn = buttons.find((b) => b.type === "submit") || buttons[0]
      if (submitBtn) {
        if (submitBtn.confirmation) {
          setConfirmation({
            isOpen: true,
            config: submitBtn.confirmation,
            pendingAction: submitBtn.action,
            pendingData: data,
          })
        } else {
          onSubmit?.(data as Record<string, unknown>, submitBtn.action)
        }
      }
    }
  }

  const handleButtonClick = (e: React.MouseEvent, btn: TsFormButton) => {
    if (btn.confirmation) {
      e.preventDefault()

      const proceedWithConfirmation = (data: FormValues) => {
        setConfirmation({
          isOpen: true,
          config: btn.confirmation!,
          pendingAction: btn.action,
          pendingData: data,
        })
      }

      if (!btn.type || btn.type === "submit") {
        // Trigger validation first
        form.handleSubmit(proceedWithConfirmation)(e)
      } else {
        // No validation for non-submit buttons
        proceedWithConfirmation(form.getValues() as FormValues)
      }
      return
    }

    // Normal flow
    if (!btn.type || btn.type === "submit") {
      setSubmittingAction(btn.action)
      // form onSubmit will be called
    } else {
      e.preventDefault()
      onSubmit?.(form.getValues() as Record<string, unknown>, btn.action)
    }
  }

  const handleConfirmationAction = (btnConfig: { action: string; confirm?: boolean }) => {
    setConfirmation((prev) => ({ ...prev, isOpen: false }))

    if (btnConfig.confirm && confirmation.pendingAction && confirmation.pendingData) {
      setSubmittingAction(confirmation.pendingAction)
      onSubmit?.(confirmation.pendingData as Record<string, unknown>, confirmation.pendingAction)
      setSubmittingAction(null)
    }
  }

  return (
    <>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onFormSubmit)} className={className}>
          <TsFormLayout layout={layout} fields={fields} />

          {/* Buttons Bar */}
          {buttons.length > 0 && (
            <div className="flex items-center justify-end gap-2 mt-6 pt-4 border-t">
              {buttons.map((btn, idx) => {
                // Map variants
                type ButtonVariant =
                  | "default"
                  | "destructive"
                  | "outline"
                  | "secondary"
                  | "ghost"
                  | "link"
                let variant: ButtonVariant = "default"
                if (btn.variant === "primary") variant = "default"
                else if (btn.variant === "danger") variant = "destructive"
                else if (
                  btn.variant === "default" ||
                  btn.variant === "destructive" ||
                  btn.variant === "outline" ||
                  btn.variant === "secondary" ||
                  btn.variant === "ghost" ||
                  btn.variant === "link"
                ) {
                  variant = btn.variant
                }

                return (
                  <Button
                    key={idx}
                    type={btn.type || "submit"}
                    variant={variant}
                    onClick={(e) => handleButtonClick(e, btn)}
                    disabled={form.formState.isSubmitting && submittingAction === btn.action}
                  >
                    {form.formState.isSubmitting && submittingAction === btn.action && (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    )}
                    {btn.label}
                  </Button>
                )
              })}
            </div>
          )}
        </form>
      </Form>

      {/* Confirmation Dialog */}
      {confirmation.config && (
        <AlertDialog
          open={confirmation.isOpen}
          onOpenChange={(open: boolean) => setConfirmation((prev) => ({ ...prev, isOpen: open }))}
        >
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{confirmation.config.title}</AlertDialogTitle>
              <AlertDialogDescription>{confirmation.config.text}</AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              {confirmation.config.buttons.map((btn, idx) =>
                btn.confirm ? (
                  <AlertDialogAction
                    key={idx}
                    onClick={() => handleConfirmationAction(btn)}
                    className={
                      btn.variant === "danger" ? "bg-destructive hover:bg-destructive/90" : ""
                    }
                  >
                    {btn.label}
                  </AlertDialogAction>
                ) : (
                  <AlertDialogCancel key={idx} onClick={() => handleConfirmationAction(btn)}>
                    {btn.label}
                  </AlertDialogCancel>
                )
              )}
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </>
  )
}

"use client"

import { format } from "date-fns"
import { enUS } from "date-fns/locale"
import { CalendarIcon, Check, ChevronsUpDown, Info, X as XIcon } from "lucide-react"

import * as React from "react"
import { ControllerRenderProps, FieldValues, useFormContext } from "react-hook-form"
import Markdown from "react-markdown"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Slider } from "@/components/ui/slider"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

import { cn } from "@/lib/utils"

import { TsTable } from "@/components/ts-web-ui/ts-table"
import { TsFieldDef, TsFieldOptions } from "./types"

interface TsFormFieldProps {
  name: string
  fieldDef: TsFieldDef
}

export function TsFormField({ name, fieldDef }: TsFormFieldProps) {
  const form = useFormContext()
  const hasError = !!fieldDef.error

  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem
          className={cn(fieldDef.hidden && "hidden", hasError && "[&_label]:text-destructive")}
        >
          {/* Label is rendered unless it's a checkbox/switch/infobox/button/separator/empty/markdown */}
          {fieldDef.type !== "checkbox" &&
            fieldDef.type !== "switch" &&
            fieldDef.type !== "infobox" &&
            fieldDef.type !== "button" &&
            fieldDef.type !== "separator" &&
            fieldDef.type !== "empty" &&
            fieldDef.type !== "markdown" && (
              <FormLabel className={cn(hasError && "text-destructive")}>
                {fieldDef.label}
                {fieldDef.required && <span className="ml-1">*</span>}
              </FormLabel>
            )}

          <FormControl>{renderWidget(field, fieldDef, name, hasError)}</FormControl>

          {/* Error message has priority over hint */}
          {hasError ? (
            <p className="text-sm text-destructive">{fieldDef.error}</p>
          ) : (
            fieldDef.hint && <FormDescription>{fieldDef.hint}</FormDescription>
          )}
          <FormMessage />
        </FormItem>
      )}
    />
  )
}

function renderWidget(
  field: ControllerRenderProps<FieldValues, string>,
  def: TsFieldDef,
  name: string,
  hasError: boolean = false
) {
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault()
      if (def.type === "number") {
        field.onChange(undefined)
      } else {
        field.onChange("")
      }
    }
  }

  // Shared classes for error state and readonly styling
  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "bg-muted/50 cursor-default focus:ring-0" : ""

  switch (def.type) {
    case "text":
    case "password":
      return (
        <Input
          type={def.type}
          placeholder={def.placeholder}
          {...field}
          value={(field.value as string) ?? ""}
          onKeyDown={handleKeyDown}
          disabled={def.disabled}
          readOnly={def.readonly}
          className={cn(errorClass, readonlyClass)}
        />
      )

    case "number":
      return (
        <Input
          type="number"
          placeholder={def.placeholder}
          {...field}
          value={(field.value as number) ?? ""}
          onChange={(e) => {
            const val = e.target.value
            field.onChange(val === "" ? undefined : e.target.valueAsNumber)
          }}
          onKeyDown={handleKeyDown}
          min={def.min}
          max={def.max}
          step={def.step}
          disabled={def.disabled}
          readOnly={def.readonly}
          className={cn(errorClass, readonlyClass)}
        />
      )

    case "textarea":
      return (
        <Textarea
          placeholder={def.placeholder}
          {...field}
          value={(field.value as string) ?? ""}
          rows={def.rows || 3}
          onKeyDown={handleKeyDown}
          disabled={def.disabled}
          readOnly={def.readonly}
          className={cn(errorClass, readonlyClass)}
        />
      )

    case "checkbox":
      return (
        <div className="flex items-center space-x-2">
          <Checkbox
            checked={!!field.value}
            onCheckedChange={field.onChange}
            disabled={def.disabled || def.readonly}
            className={cn(hasError && "border-destructive data-[state=checked]:bg-destructive")}
          />
          <FormLabel className={cn("font-normal cursor-pointer", hasError && "text-destructive")}>
            {def.label}
            {def.required && <span className="ml-1">*</span>}
          </FormLabel>
        </div>
      )

    case "switch":
      return (
        <div className="flex items-center space-x-2">
          <Switch
            checked={!!field.value}
            onCheckedChange={field.onChange}
            disabled={def.disabled || def.readonly}
            className={cn(
              hasError &&
                "data-[state=checked]:bg-destructive data-[state=unchecked]:bg-destructive/30"
            )}
          />
          <FormLabel className={cn("font-normal cursor-pointer", hasError && "text-destructive")}>
            {def.label}
            {def.required && <span className="ml-1">*</span>}
          </FormLabel>
        </div>
      )

    case "radio":
      return (
        <RadioGroup
          onValueChange={field.onChange}
          defaultValue={field.value}
          disabled={def.disabled || def.readonly}
          className={cn("flex flex-col space-y-1", hasError && "[&_button]:border-destructive")}
        >
          {(def.options || []).map((opt: TsFieldOptions | string) => {
            const value = typeof opt === "string" ? opt : String(opt.value)
            const label = typeof opt === "string" ? opt : opt.label
            return (
              <div key={value} className="flex items-center space-x-2">
                <RadioGroupItem value={value} id={`${field.name}-${value}`} />
                <FormLabel
                  htmlFor={`${field.name}-${value}`}
                  className={cn("font-normal cursor-pointer", hasError && "text-destructive")}
                >
                  {label}
                </FormLabel>
              </div>
            )
          })}
        </RadioGroup>
      )

    case "button-group":
      return (
        <ToggleGroup
          type="single"
          value={field.value}
          onValueChange={field.onChange}
          disabled={def.disabled || def.readonly}
          className={cn(
            hasError && "[&_button]:border-destructive [&_button[data-state=on]]:bg-destructive"
          )}
        >
          {(def.options || []).map((opt: TsFieldOptions | string) => {
            // format value/label or object
            const value = typeof opt === "string" ? opt.split("/")[0] : String(opt.value)
            const label = typeof opt === "string" ? opt.split("/").pop() : opt.label

            return (
              <ToggleGroupItem key={value} value={value} aria-label={label}>
                {label}
              </ToggleGroupItem>
            )
          })}
        </ToggleGroup>
      )

    case "slider":
      return (
        <div className="py-4">
          <Slider
            defaultValue={[field.value || def.min || 0]}
            max={def.max || 100}
            min={def.min || 0}
            step={def.step || 1}
            onValueChange={(vals: number[]) => field.onChange(vals[0])}
            disabled={def.disabled || def.readonly}
            className={cn(
              hasError && "[&_[role=slider]]:border-destructive [&_[role=slider]]:bg-destructive"
            )}
          />
        </div>
      )

    case "select":
      return (
        <Select
          onValueChange={field.onChange}
          value={field.value}
          disabled={def.disabled || def.readonly}
        >
          <SelectTrigger className={cn(errorClass, readonlyClass)}>
            <SelectValue placeholder={def.placeholder || "Select..."} />
          </SelectTrigger>
          <SelectContent>
            {(def.options || []).map((opt: TsFieldOptions | string) => {
              const value = typeof opt === "string" ? opt : String(opt.value)
              const label = typeof opt === "string" ? opt : opt.label
              return (
                <SelectItem key={value} value={value}>
                  {label}
                </SelectItem>
              )
            })}
          </SelectContent>
        </Select>
      )

    case "combobox":
      return <ComboboxWidget field={field} def={def} hasError={hasError} />

    case "multiselect":
      return <MultiSelectWidget field={field} def={def} hasError={hasError} />

    case "date":
      return (
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant={"outline"}
              className={cn(
                "w-full justify-start text-left font-normal",
                !field.value && "text-muted-foreground",
                errorClass,
                readonlyClass
              )}
              disabled={def.disabled || def.readonly}
            >
              <CalendarIcon className="mr-2 h-4 w-4" />
              {field.value ? (
                format(field.value as Date, "PPP", { locale: enUS })
              ) : (
                <span>{def.placeholder || "Pick a date"}</span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-auto p-0" align="start">
            <Calendar
              mode="single"
              selected={field.value as Date}
              onSelect={field.onChange}
              initialFocus
              locale={enUS}
            />
          </PopoverContent>
        </Popover>
      )

    case "datetime":
      return (
        <Input
          type="datetime-local"
          {...field}
          value={field.value ? new Date(field.value as string).toISOString().slice(0, 16) : ""}
          onChange={(e) => field.onChange(e.target.value ? new Date(e.target.value) : undefined)}
          disabled={def.disabled}
          readOnly={def.readonly}
          className={cn(errorClass, readonlyClass)}
        />
      )

    case "file":
    case "image":
      return (
        <div className="grid w-full max-w-sm items-center gap-1.5">
          <Input
            type="file"
            accept={def.accept || (def.type === "image" ? "image/*" : undefined)}
            multiple={def.multiple}
            disabled={def.disabled}
            readOnly={def.readonly}
            className={cn(errorClass, readonlyClass, def.readonly && "pointer-events-none")}
            onChange={(e) => {
              const files = e.target.files
              if (def.multiple) {
                field.onChange(files)
              } else {
                field.onChange(files?.[0])
              }
            }}
          />
        </div>
      )

    case "infobox": {
      type AlertVariant = "default" | "destructive"
      const variant: AlertVariant = def.variant === "destructive" ? "destructive" : "default"
      return (
        <Alert variant={variant}>
          <Info className="h-4 w-4" />
          <AlertTitle>{def.label || "Info"}</AlertTitle>
          <AlertDescription>
            {(def.value as React.ReactNode) || def.content || "Infobox content"}
          </AlertDescription>
        </Alert>
      )
    }

    case "markdown":
      return (
        <div className="prose dark:prose-invert max-w-none p-4 border rounded-md bg-muted/50 text-sm">
          <Markdown>{(def.value as string) || def.content || ""}</Markdown>
        </div>
      )

    case "table":
      return (
        <div className="border rounded-md p-2">
          <TsTable
            data={(field.value as Record<string, unknown>[]) || []}
            columnDefinitions={def.columns || []}
            showCreateButton={def.showCreateButton}
          />
        </div>
      )

    case "button":
      return (
        <Button
          variant={(def.variant as "default") || "default"}
          className="w-full"
          onClick={(e) => {
            e.preventDefault()
            // Dispatch custom event for bubbling
            const event = new CustomEvent("form-field-action", {
              detail: { field: name, action: def.action },
              bubbles: true,
            })
            e.currentTarget.dispatchEvent(event)
          }}
        >
          {def.label}
        </Button>
      )

    case "separator":
      // Separator - visual element without value
      return (
        <div className="py-2">
          {def.label ? (
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <span className="w-full border-t" />
              </div>
              <div className="relative flex justify-center text-xs uppercase">
                <span className="bg-background px-2 text-muted-foreground font-medium">
                  {def.label}
                </span>
              </div>
            </div>
          ) : (
            <hr className="border-t" />
          )}
        </div>
      )

    case "empty":
      // Empty placeholder for layout purposes
      return <div className="min-h-[40px]" />

    case "relationship":
      // Relationship picker for entity selection
      return <RelationshipWidget field={field} def={def} hasError={hasError} />

    // Fallback for not implemented
    default:
      return (
        <div className="p-2 border border-destructive/50 text-destructive text-sm rounded bg-destructive/10">
          Unsupported widget: {def.type}
        </div>
      )
  }
}

function ComboboxWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsFieldDef
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [searchValue, setSearchValue] = React.useState("")
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    const value = typeof opt === "string" ? opt : String(opt.value)
    const label = typeof opt === "string" ? opt : opt.label
    return { value, label }
  })

  // Allow custom value if not found
  const showCustom =
    def.allowCustom &&
    searchValue &&
    !options.find((o) => o.label.toLowerCase() === searchValue.toLowerCase())

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "bg-muted/50 cursor-default" : ""

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn("w-full justify-between", errorClass, readonlyClass)}
          disabled={def.disabled || def.readonly}
        >
          {field.value
            ? (options.find((framework) => framework.value === field.value)?.label ??
              (field.value as string))
            : def.placeholder || "Select..."}
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-full p-0">
        <Command>
          <CommandInput
            placeholder={def.placeholder || "Search..."}
            value={searchValue}
            onValueChange={setSearchValue}
          />
          <CommandList>
            <CommandEmpty>
              {showCustom ? (
                <div
                  className="p-2 cursor-pointer hover:bg-muted text-sm"
                  onClick={() => {
                    field.onChange(searchValue)
                    setOpen(false)
                  }}
                >
                  Use: &quot;{searchValue}&quot;
                </div>
              ) : (
                "Not found."
              )}
            </CommandEmpty>
            <CommandGroup>
              {options.map((framework) => (
                <CommandItem
                  key={framework.value}
                  value={framework.label}
                  onSelect={(currentValue: string) => {
                    const original = options.find(
                      (o) => o.label.toLowerCase() === currentValue.toLowerCase()
                    )
                    field.onChange(original ? original.value : currentValue)
                    setOpen(false)
                  }}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      field.value === framework.value ? "opacity-100" : "opacity-0"
                    )}
                  />
                  {framework.label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

function MultiSelectWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsFieldDef
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const selectedValues: string[] = Array.isArray(field.value) ? (field.value as string[]) : []
  const options = (def.options || []).map((opt: TsFieldOptions | string) => {
    const value = typeof opt === "string" ? opt : String(opt.value)
    const label = typeof opt === "string" ? opt : opt.label
    return { value, label }
  })

  const toggleValue = (val: string) => {
    const newValues = selectedValues.includes(val)
      ? selectedValues.filter((v) => v !== val)
      : [...selectedValues, val]
    field.onChange(newValues)
  }

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "bg-muted/50 cursor-default" : ""

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          className={cn("w-full justify-between h-auto min-h-[40px]", errorClass, readonlyClass)}
          disabled={def.disabled || def.readonly}
        >
          <div className="flex flex-wrap gap-1">
            {selectedValues.length > 0 ? (
              selectedValues.map((val) => (
                <Badge key={val} variant="secondary" className="mr-1">
                  {options.find((o) => o.value === val)?.label || val}
                  <XIcon
                    className="ml-1 h-3 w-3 cursor-pointer"
                    onClick={(e) => {
                      e.stopPropagation()
                      toggleValue(val)
                    }}
                  />
                </Badge>
              ))
            ) : (
              <span className="text-muted-foreground">{def.placeholder || "Select..."}</span>
            )}
          </div>
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-full p-0">
        <Command>
          <CommandInput placeholder={def.placeholder || "Search..."} />
          <CommandList>
            <CommandEmpty>Not found.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt.value}
                  value={opt.label}
                  onSelect={() => toggleValue(opt.value)}
                >
                  <Check
                    className={cn(
                      "mr-2 h-4 w-4",
                      selectedValues.includes(opt.value) ? "opacity-100" : "opacity-0"
                    )}
                  />
                  {opt.label}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/**
 * Relationship Widget - allows selecting entities from a relational table
 * Supports single or multiple selection modes
 */
function RelationshipWidget({
  field,
  def,
  hasError = false,
}: {
  field: ControllerRenderProps<FieldValues, string>
  def: TsFieldDef
  hasError?: boolean
}) {
  const [open, setOpen] = React.useState(false)
  const [searchValue, setSearchValue] = React.useState("")

  // Configuration from field definition
  const mode = def.mode || "single"
  const targetEntity = def.targetEntity || ""

  const displayFields = React.useMemo(() => def.displayFields || ["name"], [def.displayFields])
  const chipDisplayFields = React.useMemo(
    () => def.chipDisplayFields || displayFields,
    [def.chipDisplayFields, displayFields]
  )

  const valueField = def.valueField || "id"
  const availableItems = React.useMemo(
    () => (def.options as unknown as Record<string, unknown>[]) || [],
    [def.options]
  )

  const errorClass = hasError ? "border-destructive focus-visible:ring-destructive" : ""
  const readonlyClass = def.readonly ? "bg-muted/50 cursor-default" : ""

  // Value parsing - can be single ID, array ID or object/objects
  const selectedValues = React.useMemo(() => {
    if (!field.value) return []
    return Array.isArray(field.value) ? (field.value as unknown[]) : [field.value]
  }, [field.value])

  /**
   * Gets display text for an item
   */
  const getDisplayText = (item: unknown, fields: string[]) => {
    if (!item) return ""
    if (typeof item !== "object") {
      // Find item by ID
      const found = availableItems.find((i) => i[valueField] === item)
      if (found) {
        return fields
          .map((f) => String(found[f]))
          .filter(Boolean)
          .join(" ")
      }
      return String(item)
    }
    const obj = item as Record<string, unknown>
    return fields
      .map((f) => String(obj[f]))
      .filter(Boolean)
      .join(" ")
  }

  /**
   * Filters items based on search text
   */
  const filteredItems = React.useMemo(() => {
    if (!searchValue) return availableItems
    const lower = searchValue.toLowerCase()
    return availableItems.filter((item) => {
      const text = displayFields
        .map((f: string) => String(item[f]))
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
      return text.includes(lower)
    })
  }, [availableItems, searchValue, displayFields])

  /**
   * Selects/removes an item
   */
  const toggleItem = (item: Record<string, unknown>) => {
    const itemValue = item[valueField]

    if (mode === "single") {
      field.onChange(itemValue)
      setOpen(false)
    } else {
      const isSelected = selectedValues.includes(itemValue)
      if (isSelected) {
        field.onChange(selectedValues.filter((v) => v !== itemValue))
      } else {
        field.onChange([...selectedValues, itemValue])
      }
    }
  }

  /**
   * Removes item from selection (for chip)
   */
  const removeItem = (itemValue: unknown) => {
    if (mode === "single") {
      field.onChange(null)
    } else {
      field.onChange(selectedValues.filter((v) => v !== itemValue))
    }
  }

  /**
   * Checks if item is selected
   */
  const isSelected = (item: Record<string, unknown>) => selectedValues.includes(item[valueField])

  return (
    <div className="space-y-2">
      {/* Selected items as chips */}
      {selectedValues.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {selectedValues.map((val) => (
            <Badge key={String(val)} variant="secondary">
              {getDisplayText(val, chipDisplayFields)}
              <XIcon
                className="ml-1 h-3 w-3 cursor-pointer hover:text-destructive"
                onClick={() => removeItem(val)}
              />
            </Badge>
          ))}
        </div>
      )}

      {/* Picker button */}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className={cn("w-full justify-between", errorClass, readonlyClass)}
            disabled={def.disabled || def.readonly}
          >
            {selectedValues.length === 0 ? (
              <span className="text-muted-foreground">
                {def.placeholder || `Select ${targetEntity}...`}
              </span>
            ) : (
              <span className="text-muted-foreground text-sm">
                {mode === "single" ? "Change selection" : "Add more"}
              </span>
            )}
            <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-full min-w-[300px] p-0" align="start">
          <Command shouldFilter={false}>
            <CommandInput
              placeholder={`Search ${targetEntity}...`}
              value={searchValue}
              onValueChange={setSearchValue}
            />
            <CommandList>
              <CommandEmpty>
                {availableItems.length === 0 ? `No items in ${targetEntity}` : "Not found."}
              </CommandEmpty>
              <CommandGroup>
                {filteredItems.map((item) => (
                  <CommandItem
                    key={String(item[valueField])}
                    value={String(item[valueField])}
                    onSelect={() => toggleItem(item)}
                  >
                    <Check
                      className={cn("mr-2 h-4 w-4", isSelected(item) ? "opacity-100" : "opacity-0")}
                    />
                    {getDisplayText(item, displayFields)}
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </div>
  )
}

"use client"

import * as React from "react"

import { Separator } from "@/components/ui/separator"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

import { TsFormField } from "./ts-form-field"
import { TsFormLayout as LayoutType, TsFieldDef, TsFormRow } from "./types"

interface TsFormLayoutProps {
  layout: LayoutType
  fields: Record<string, TsFieldDef>
}

export function TsFormLayout({ layout, fields }: TsFormLayoutProps) {
  if (layout.tabs) {
    return (
      <Tabs defaultValue={layout.tabs[0].label} className="w-full">
        <TabsList className="w-full justify-start">
          {layout.tabs.map((tab, index) => (
            <TabsTrigger key={index} value={tab.label}>
              {tab.label}
            </TabsTrigger>
          ))}
        </TabsList>
        {layout.tabs.map((tab, index) => (
          <TabsContent key={index} value={tab.label} className="space-y-4 pt-4">
            {renderRows(tab.rows, fields)}
          </TabsContent>
        ))}
      </Tabs>
    )
  }

  if (layout.rows) {
    return <div className="space-y-4">{renderRows(layout.rows, fields)}</div>
  }

  return null
}

function renderRows(rows: TsFormRow[], fields: Record<string, TsFieldDef>) {
  return rows.map((row, rowIndex) => {
    // Calculate grid template columns based on widths
    // Default width is 1fr if not specified
    const gridTemplateColumns = row.map((item) => item.width || "1fr").join(" ")

    return (
      <div key={rowIndex} className="grid gap-4 items-start" style={{ gridTemplateColumns }}>
        {row.map((item, colIndex) => {
          if (item.type === "empty") {
            return <div key={colIndex} />
          }

          if (item.type === "separator") {
            return (
              <div key={colIndex} className="col-span-full py-2">
                {item.label && (
                  <h4 className="text-sm font-medium text-muted-foreground mb-2">{item.label}</h4>
                )}
                <Separator />
              </div>
            )
          }

          const fieldDef = fields[item.field]
          if (!fieldDef) {
            return (
              <div key={colIndex} className="text-destructive text-sm">
                Field &apos;{item.field}&apos; not found
              </div>
            )
          }

          return <TsFormField key={colIndex} name={item.field} fieldDef={fieldDef} />
        })}
      </div>
    )
  })
}

import { z } from "zod"

import { TsFieldDef } from "./types"

export function generateZodSchema(fields: Record<string, TsFieldDef>) {
  const shape: Record<string, z.ZodTypeAny> = {}

  Object.entries(fields).forEach(([key, def]) => {
    if (def.type === "separator" || def.type === "empty" || def.type === "button") {
      return
    }

    let schema: z.ZodTypeAny

    switch (def.type) {
      case "number":
      case "slider":
        schema = z.number()
        if (def.min !== undefined) schema = (schema as z.ZodNumber).min(def.min)
        if (def.max !== undefined) schema = (schema as z.ZodNumber).max(def.max)

        // Pokud není required, povolíme null/undefined
        if (!def.required) {
          schema = schema.nullish()
        }
        break

      case "checkbox":
      case "switch":
        schema = z.boolean().default(false)
        break

      case "date":
      case "datetime":
        schema = z.date()
        if (!def.required) schema = schema.nullish()
        break

      default: // text, select, etc. (mostly strings)
        if (def.required) {
          schema = z.string().min(1, { message: "This field is required" })
        } else {
          schema = z.string().optional().or(z.literal(""))
        }
        break
    }

    shape[key] = schema
  })

  return z.object(shape)
}
